            $manager = m::mock(FilesystemManager::class);
            $manager->shouldReceive('disk')->with('foo')->andReturn(m::mock(Filesystem::class));
            $manager->shouldReceive('disk')->with('bar')->andReturn(m::mock(Filesystem::class));

